  for (String id in ids) {
    int x = idToX[id]!;
    int y = idToY[id]!;
    String state = _getCondition(x, y);
    currentStates[id] = state;
  }

  List<String> states = ids.map((id) => '$id:${currentStates[id]}').toList()
    ..sort((a, b) {
      List<String> pa = a.split(':');
      List<String> pb = b.split(':');
      int cmp = currentStates[pa[0]]!.compareTo(currentStates[pb[0]]!);
      if (cmp != 0) return cmp;
      return pa[0].compareTo(pb[0]);
    });

