}

String _getCondition(int x, int y) {
  int distance = (x - 20).abs() + (y - 40).abs();
  if (distance <= 10) return 'excellent';
  if (distance <= 20) return 'good';
  if (distance <= 30) return 'fair';
  if (distance <= 40) return 'weak';
