        if (previousId != null && previousState == 'lost') {
          output.write('lost|');
        }
        output.write(previous);
        if (current.containsKey(previousId!)) {
          output.write('->$current[$previousId] ');
        } else {
          output.write('->dead ');
        }
      }
      previous = '$id:$value';
      previousId = id;
      previousState = state;
    }
  }
  if (previousId != null && previousState == 'lost') {
    output.write('lost');
  }
  return output.toString().trim();
}

