  liveNeighbors.sort((a, b) {
    int liveA = a.where((v) => v == 1).length;
    int liveB = b.where((v) => v == 1).length;
    if (liveA != liveB) return liveB.compareTo(liveA);
    int sumA = a.fold(0, (sum, val) => sum + val);
    int sumB = b.fold(0, (sum, val) => sum + val);
    if (sumA != sumB) return sumA.compareTo(sumB);
    return a.join(',').compareTo(b.join(','));
  });

  return liveNeighbors.map((neighbors) => neighbors.join(',')).join(';');
}

