int pow(int base, int exp, int mod) {
  int result = 1 % mod;
  int power = base % mod;
  int exponent = exp;

  while (exponent > 0) {
    if ((exponent & 1) == 1) {
      result = (result * power) % mod;
    }
    power = (power * power) % mod;
    exponent >>= 1;
  }

  return result;
}

