    int code = password.codeUnitAt(i);
    if (code >= 48 && code <= 57) {
      hasDigit = true;
    } else if (code >= 65 && code <= 90) {
      hasUpper = true;
    } else if (code >= 97 && code <= 122) {
      hasLower = true;
    }
  }

