            password.substring(right, left - 1 + 1).reversed
        ? password
        : password.substring(0, left) + password.substring(right + 1);

    password = password.substring(0, left) +
        String.fromCharCode(temp) +
        password.substring(left + 1);

    left++;
    right--;
  }

  return int.parse(password.substring(2, password.length - 2));
}

