List<int> fn0(String dna, int k, int t) {
  const map = {'A': 0, 'C': 1, 'G': 2, 'T': 0};
  int n = dna.length;
  if (k <= 0 || t < 0 || 2 * t >= n) return [];
  List<int> dp = List<int>.filled(n + 1, -1);
  dp[0] = 0;
  for (int i = 0; i < n; i++) {
    if (dp[i] == -1) continue;
    for (int j = i + 1; j <= n && j - i <= k; j++) {
      int m = map[dna[j - 1]] ?? 0;
      if (m == 0) continue;
      int c = dp[i] ^ m;
      int len = j - i;
      int lo = len - t;
      int hi = len - t + 2;
      for (int prev = lo; prev <= hi; prev++) {
        if (prev >= 0 && dp[prev] == c) {
          dp[j] = j;
          break;
        }
      }
    }
  }
  List<int> result = [];
  for (int i = t; i <= n - t; i++) {
    if (dp[i] == i) result.add(i);
  }
  return result;
}

