  final Map<String, int> baseToRank = {'A': 0, 'C': 1, 'G': 2, 'T': 3};

  List<int> patternRank = List<int>.filled(m, 0);
  for (int i = 0; i < m; i++) {
    patternRank[i] = baseToRank[pattern[i]]!;
  }

  List<int> prefixA = List<int>.filled(n + 1, 0);
  List<int> prefixC = List<int>.filled(n + 1, 0);
  List<int> prefixG = List<int>.filled(n + 1, 0);

