    prefixA[i + 1] = prefixA[i] + (dna[i] == 'A' ? 1 : 0);
    prefixC[i + 1] = prefixC[i] + (dna[i] == 'C' ? 1 : 0);
    prefixG[i + 1] = prefixG[i] + (dna[i] == 'G' ? 1 : 0);
  }

  int countAtPosition(int base, int pos) {
    return prefixA[pos] - prefixA[pos - base - 1];
  }

  for (int i = 0; i <= n - m; i++) {
    bool match = true;
    for (int j = 0; j < m; j++) {
      if (charToIndex[dna[i + j]] != patternRank[j]) {
        match = false;
        break;
      }
    }
    if (match) {
