List<String> fn0(List<int> rolls, int targetSum, int windowSize) {
  List<String> results = [];
  int left = 0;
  int currentSum = 0;
  for (int right = 0; right < rolls.length; right++) {
    currentSum += rolls[right];
    if (right - left + 1 > windowSize) {
      currentSum -= rolls[left];
      left++;
    }
    if (currentSum == targetSum && right - left + 1 == windowSize) {
      String encoded = '';
      for (int i = left; i <= right; i++) {
        encoded += rolls[i].toString();
        if (i < right) encoded += ',';
      }
      results.add(encoded);
    }
  }
  results.sort();
  return results;
}

