@pragma('vm:entry-point')
List<int> fn0(List<int> dailyVolumes, int minNetDays) {
  int n = dailyVolumes.length;
  if (n == 0 || minNetDays < 1) return [];
  List<int> maxNet = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    maxNet[i] = dailyVolumes[i] > 0 ? dailyVolumes[i] : 0;
  }
  int bestStart = 0;
  int bestLen = 0;
  int bestSum = maxNet[0];
  int left = 0;
  int currentSum = 0;
  for (int right = 0; right < n; right++) {
    currentSum += maxNet[right];
    while (right - left + 1 > minNetDays && currentSum > bestSum) {
      currentSum -= maxNet[left];
      left++;
    }
    if (right - left + 1 >= minNetDays && currentSum > bestSum) {
      bestSum = currentSum;
      bestStart = left;
      bestLen = right - left + 1;
    }
  }
  List<int> result = List.filled(bestLen, 0);
  for (int i = 0; i < bestLen; i++) {
    result[i] = dailyVolumes[bestStart + i];
  }
  return result;
}

