@pragma('vm:entry-point')
List<int> fn0(List<int> modules, int cycleLength) {
  if (cycleLength <= 0) {
    return <int>[];
  }

  final int n = modules.length;
  final List<int> cycle = <int>[];
  final List<int> offsets = <int>[];
  int currentOffset = 0;

  for (int i = 0; i < cycleLength; i++) {
    cycle.add(modules[i % n]);
    offsets.add(currentOffset);
    currentOffset += modules[i % n];
  }

  int totalOffset = 0;
  for (final int offset in offsets) {
    totalOffset += offset;
  }

  final List<int> results = <int>[];
  for (int i = 0; i < modules.length; i++) {
    int cumulative = 0;
    int cycleIndex = 0;
    int cycleCount = 0;

    for (int j = 0; j < modules.length; j++) {
      final int index = (i + j) % n;
      final int value = modules[index];

      if (value == 0) {
        cumulative += cycle[cycleIndex % cycleLength];
        cycleIndex++;
        cycleCount++;
      } else {
        cumulative += offsets[cycleIndex % cycleLength];
        cycleIndex++;
        cycleCount++;

        if (cycleCount == cycleLength) {
          cumulative -= totalOffset;
          cycleCount = 0;
        }
      }

      if (cumulative >= value) {
        results.add(j + 1);
        break;
      }
    }
  }

  return results;
}

