List<int> fn0(List<int> packetSizes, int maxChunkSize) {
  int n = packetSizes.length;
  List<int> cost = List.filled(n, 0);
  List<int> dp = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    if (packetSizes[i] > maxChunkSize) {
      cost[i] = 1 << 30;
    } else {
      cost[i] = packetSizes[i];
    }
    dp[i] = cost[i];
  }
  for (int len = 2; len <= n; len++) {
    List<int> prefixSum = List.filled(len, 0);
    for (int i = 0; i < len; i++) {
      if (packetSizes[i] > maxChunkSize) {
        prefixSum[i] = 1 << 30;
      } else {
        prefixSum[i] = packetSizes[i];
      }
      if (i > 0) {
        prefixSum[i] += prefixSum[i - 1];
      }
    }
    for (int i = len - 1; i < n; i++) {
      int splitPos = i - len + 1;
      int sum = packetSizes[i];
      if (splitPos > 0) {
        sum += prefixSum[splitPos - 1];
      }
      if (packetSizes[i] > maxChunkSize) {
        cost[i] = 1 << 30;
      } else {
        cost[i] = sum + dp[splitPos - 1];
      }
      dp[i] = cost[i] < dp[i] ? cost[i] : dp[i];
    }
  }
  return dp;
}

