  final Set<int> result = <int>{};

  final List<List<bool>> visited = List.generate(
    height,
    (_) => List<bool>.filled(width, false),
  );

  final List<List<int>> directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  final List<List<int>> queue = <List<int>>[];

  for (int r = 0; r < height; r++) {
    for (int c = 0; c < width; c++) {
      if (visited[r][c]) continue;

      int count = 0;
      final List<List<int>> area = <List<int>>[];
      final List<List<int>> perimeter = <List<int>>[];

      bool isValid(int nr, int nc) {
        return nr >= 0 && nr < height && nc >= 0 && nc < width;
      }

