      while (queue.isNotEmpty) {
        final List<int> current = queue.removeAt(0);
        final int cr = current[0];
        final int cc = current[1];

        area.add([cr, cc]);
        count++;

        for (final List<int> d in directions) {
          final int nr = cr + d[0];
          final int nc = cc + d[1];
          if (isValid(nr, nc) && !visited[nr][nc]) {
            visited[nr][nc] = true;
            queue.add([nr, nc]);
          }
        }
      }

      int perim = 0;

      for (final List<int> pos in area) {
        final int r2 = pos[0];
        final int c2 = pos[1];

        for (final List<int> d in directions) {
          final int nr = r2 + d[0];
          final int nc = c2 + d[1];
          if (!isValid(nr, nc)) {
            perim++;
          }
        }
      }

      if (count >= numItems && perim <= 2) {
        for (final List<int> pos in area) {
          result.add((pos[0] * width) + pos[1]);
        }
      }
    }
  }

  return result;
}

