class Quaternion {
  double w, x, y, z;

  Quaternion(this.w, this.x, this.y, this.z);

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      this.w + other.w,
      this.x + other.x,
      this.y + other.y,
      this.z + other.z,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(
      this.w - other.w,
      this.x - other.x,
      this.y - other.y,
      this.z - other.z,
    );
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      this.w * scalar,
      this.x * scalar,
      this.y * scalar,
      this.z * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    double nw = this.w * other.w - this.x * other.x - this.y * other.y - this.z * other.z;
    double nx = this.w * other.x + this.x * other.w + this.y * other.z - this.z * other.y;
    double ny = this.w * other.y - this.x * other.z + this.y * other.w + this.z * other.x;
    double nz = this.w * other.z + this.x * other.y - this.y * other.x + this.z * other.w;
    return Quaternion(nw, nx, ny, nz);
  }

  Quaternion conjugate() {
    return Quaternion(this.w, -this.x, -this.y, -this.z);
  }

  Quaternion inverse() {
    double normSq = this.norm();
    if (normSq == 0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return conjugate() * (1 / normSq);
  }

  double norm() {
    return sqrt(pow(w, 2) + pow(x, 2) + pow(y, 2) + pow(z, 2));
  }

  Quaternion normalized() {
    double n = norm();
    if (n == 0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(w / n, x / n, y / n, z / n);
  }

  @override
  String toString() {
    return '($w, $x, $y, $z)';
  }
}

