double fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return 0.0;
  int rows = grid.length, cols = grid[0].length;
  List<double> maxHeights = List<double>.generate(cols, (c) => 0.0);
  List<double> minHeights = List<double>.generate(cols, (c) => double.infinity);
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      maxHeights[c] = maxHeights[c] > grid[r][c] ? maxHeights[c] : grid[r][c];
      minHeights[c] = minHeights[c] < grid[r][c] ? minHeights[c] : grid[r][c];
    }
  }
  double total = 0.0;
  for (int c = 0; c < cols; c++) {
    total += maxHeights[c] - minHeights[c];
  }
  return total / cols;
}

