@pragma('vm:entry-point')
double fn0(List<int> schedule) {
  if (schedule.length < 2) return 0.0;
  int n = schedule.length;
  List<int> dp = List.filled(n, 0);
  for (int i = 0; i < n; i++) {
    dp[i] = schedule[i];
  }
  for (int i = 2; i < n; i++) {
    dp[i] = schedule[i] + (dp[i - 2] > dp[i - 1] ? dp[i - 2] : dp[i - 1]);
  }
  return dp[n - 1].toDouble();
}

