double fn0(int startDay, int endDay, List<int> restDays) {
  int totalDays = endDay - startDay;
  int numCycles = totalDays ~/ restDays.length;
  int remainderDays = totalDays % restDays.length;
  double sum = 0.0;
  for (int i = 0; i < restDays.length; i++) {
    int cycleIndex = i < remainderDays ? i : numCycles + remainderDays;
    sum += restDays[cycleIndex];
  }
  return sum;
}

