double fn0(int size) {
  if (size <= 1) return 0.0;
  int totalPairs = size * (size - 1) ~/ 2;
  int evenPairs = 0;
  for (int i = 0; i < size; i++) {
    for (int j = i + 1; j < size; j++) {
      int sum = i + j;
      if (sum.isEven) evenPairs++;
    }
  }
  return evenPairs / totalPairs;
}

