@pragma('vm:never-inline')
@pragma('vm:entry-point')
double fn0(List<List<int>> grid, int threshold) {
  int rows = grid.length;
  if (rows == 0) return 0.0;
  int cols = grid[0].length;
  if (cols == 0) return 0.0;
  int count = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (grid[r][c] >= threshold) {
        bool leftOk = (c == 0) || (grid[r][c - 1] >= threshold);
        bool rightOk = (c == cols - 1) || (grid[r][c + 1] >= threshold);
        bool topOk = (r == 0) || (grid[r - 1][c] >= threshold);
        bool bottomOk = (r == rows - 1) || (grid[r + 1][c] >= threshold);
        if (leftOk || rightOk || topOk || bottomOk) {
          count++;
        }
      }
    }
  }
  return count / (rows * cols);
}

