double fn0(List<List<int>> ledger, int k) {
  if (ledger.isEmpty || k < 0 || k >= ledger.length) {
    return 0.0;
  }
  List<int> sorted = List.from(ledger);
  sorted.sort((a, b) {
    int diffA = (a[0] - a[1]).abs();
    int diffB = (b[0] - b[1]).abs();
    if (diffA != diffB) {
      return diffB.compareTo(diffA);
    }
    if (a[0] != b[0]) {
      return a[0].compareTo(b[0]);
    }
    return a[1].compareTo(b[1]);
  });
  return sorted[k][0] - sorted[k][1];
}

