double fn0(List<int> samples, int windowSize, int maxDeviation) {
  if (windowSize <= 0 || samples.length < windowSize) {
    return 0.0;
  }

  int validCount = 0;
  for (int i = 0; i <= samples.length - windowSize; i++) {
    int minVal = samples[i];
    int maxVal = samples[i];

    for (int j = i + 1; j < i + windowSize; j++) {
      if (samples[j] < minVal) {
        minVal = samples[j];
      }
      if (samples[j] > maxVal) {
        maxVal = samples[j];
      }
    }

    if (maxVal - minVal <= maxDeviation) {
      validCount++;
    }
  }

  return validCount / (samples.length - windowSize + 1);
}

