int fn0(List<List<int>> samples, int baseIndex, int numPoints) {
  if (samples.isEmpty || numPoints <= 0 || numPoints > samples.length) return -1;
  if (baseIndex < 0 || baseIndex >= samples.length) return -1;
  for (int i = 0; i < samples.length; i++) {
