  for (int i = 0; i < samples.length; i++) {
    int dx = samples[i][0] - samples[baseIndex][0];
    int dy = samples[i][1] - samples[baseIndex][1];
    dists.add(dx * dx + dy * dy);
  }
  int minDist = dists[0];
  int maxDist = dists[0];
  for (int i = 1; i < dists.length; i++) {
    if (dists[i] < minDist) minDist = dists[i];
    if (dists[i] > maxDist) maxDist = dists[i];
  }
  int target = minDist + (maxDist - minDist) ~/ numPoints;
  dists.sort();
  int lo = 0, hi = dists.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) ~/ 2;
    if (dists[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return lo < dists.length ? lo : -1;
}

