@pragma('vm:never-inline')
@pragma('vm:entry-point')
bool fn0(List<int> packetSizes, int maxPacketSize) {
  if (packetSizes.isEmpty || maxPacketSize <= 0) {
    return false;
  }

  List<int> remainingSizes = List<int>.from(packetSizes);
  remainingSizes.sort();

  List<int> binA = [];
  List<int> binB = [];

  int placeInA(int size) {
    int lo = 0;
    int hi = binA.length;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (binA[mid] < size) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  int placeInB(int size) {
    int lo = 0;
    int hi = binB.length;
    while (lo < hi) {
      int mid = (lo + hi) ~/ 2;
      if (binB[mid] < size) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  for (int size in remainingSizes) {
    if (size <= 0 || size > maxPacketSize) {
      return false;
    }

    int aIdx = placeInA(size);
    int bIdx = placeInB(size);

    if (aIdx == 0 && bIdx == 0) {
      return false;
    }

    if (aIdx < binA.length) {
      if (binA[aIdx] == size) {
        binA.removeAt(aIdx);
        continue;
      }
    }

    if (bIdx < binB.length) {
      if (binB[bIdx] == size) {
        binB.removeAt(bIdx);
        continue;
      }
    }

    if (binA.length == 0) {
      if (binB.length == 0) {
        return false;
      }

      int lastB = binB.last;
      if (size + lastB <= maxPacketSize) {
        binB.removeLast();
      } else {
        return false;
      }
    } else {
      int lastA = binA.last;
      if (size + lastA <= maxPacketSize) {
        binA.removeLast();
      } else {
        return false;
      }
    }

    binA.insert(aIdx, size);
    binB.insert(bIdx, size);
  }

  int aSum = binA.fold<int>(0, (sum, s) => sum + s);
  int bSum = binB.fold<int>(0, (sum, s) => sum + s);

  return aSum == bSum;
}

