List<int> fn0(List<String> rows) {
  if (rows.isEmpty) return [];
  final heights = <int>[];
  final widths = <int>[];
  for (final row in rows) {
    final trimmed = row.trim();
    if (trimmed.isEmpty) continue;
    final parts = trimmed.split('|');
    final height = int.tryParse(parts[0]);
    final width = int.tryParse(parts[1]);
    if (height != null && width != null && height > 0 && width > 0) {
      heights.add(height);
      widths.add(width);
    }
  }
  if (heights.isEmpty) return [];
  final area = heights.asMap()
      .entries
      .fold((prev, e) => prev * e.key + e.value, 0);
  final result = <int>[];
  var currentArea = 0;
  var currentHeight = 0;
  var currentWidth = 1;
  for (var i = 0; i < heights.length; i++) {
    currentArea += heights[i] * currentWidth;
    currentHeight += heights[i];
    if (i == heights.length - 1 || currentArea > area) {
      result.add(currentHeight);
      result.add(currentWidth);
      currentArea = 0;
      currentHeight = 0;
      currentWidth = 1;
    } else {
      currentWidth++;
    }
  }
  return result;
}

