List<int> fn0(List<List<int>> grid, int k) {
  int n = grid.length;
  if (n == 0) return [];
  int m = grid[0].length;
  if (m == 0) return [];
  List<List<int>> costs = List.generate(n, (_) => List.filled(m, 0));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      int sum = 0;
      for (int di = -1; di <= 1; di++) {
        for (int dj = -1; dj <= 1; dj++) {
          if (di == 0 && dj == 0) continue;
          int ni = i + di;
          int nj = j + dj;
          if (ni >= 0 && ni < n && nj >= 0 && nj < m) {
            sum += grid[ni][nj];
          }
        }
      }
      costs[i][j] = sum;
    }
  }
  List<int> indices = List.generate(n * m, (idx) => idx);
  indices.sort((a, b) {
    int rowA = a ~/ m;
    int colA = a % m;
    int rowB = b ~/ m;
    int colB = b % m;
    int costCompare = costs[rowB][colB].compareTo(costs[rowA][colA]);
    if (costCompare != 0) {
      return costCompare;
    }
    if (rowA != rowB) {
      return rowA.compareTo(rowB);
    }
    return colA.compareTo(colB);
  });
  return indices.sublist(0, k).map((idx) => idx).toList();
}

