Set<int> _combinations(List<int> elements, int k) {
  Set<int> result = {};
  _generateCombinations(elements, k, 0, [], result);
  return result;
}

void _generateCombinations(List<int> elements, int k, int start, List<int> current, Set<int> result) {
  if (current.length == k) {
    result.add(_hashString(current.map((code) => String.fromCharCode(code + 65)).join('')));
    return;
  }
  for (int i = start; i < elements.length; i++) {
    current.add(elements[i]);
    _generateCombinations(elements, k, i + 1, current, result);
    current.removeLast();
  }
}

int _hashString(String str) {
  int hash = 0;
  for (int i = 0; i < str.length; i++) {
    hash = hash * 31 + str.codeUnitAt(i);
  }
  return hash;
}

