List<int> fn0(List<int> digits, int minChecksum) {
  if (digits.isEmpty) return [];
  if (minChecksum <= 0) return [0];
  int left = 0;
  int right = digits.length;
  while (left < right) {
    int mid = (left + right) ~/ 2;
    if (computeChecksum(digits.sublist(0, mid)) >= minChecksum) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  if (left == 0) return [0];
  int best = left > 1 ? computeChecksum(digits.sublist(0, left)) : 0;
  int bestLen = left;
  for (int len = 1; len <= digits.length; len++) {
    int sum = 0;
    for (int i = 0; i < len; i++) {
      sum += digits[i];
    }
    if (sum >= minChecksum && sum < best) {
      best = sum;
      bestLen = len;
    }
    for (int i = len; i < digits.length; i++) {
      sum += digits[i] - digits[i - len];
      if (sum >= minChecksum && sum < best) {
        best = sum;
        bestLen = len;
      }
    }
  }
  return [bestLen, best];
}

int computeChecksum(List<int> digits) {
  int sum = 0;
  for (int i = 0; i < digits.length; i++) {
    sum += digits[i] * (i + 1);
  }
  return sum;
}

