Set<int> fn0(List<int> requests, int currentFloor, int capacity) {
  if (capacity <= 0 || requests.isEmpty) return <int>{};

  final Set<int> pending = <int>{};
  for (final int r in requests) {
    if (r != currentFloor) pending.add(r);
  }

  if (pending.isEmpty) return pending;

  final Map<int, int> freq = <int, int>{};
  final Map<int, Set<int>> groups = <int, Set<int>>{};
  for (final int r in pending) {
    freq[r] = (freq[r] ?? 0) + 1;
    groups.putIfAbsent(r.abs(), () => <int>{});
    groups[r.abs()]!.add(r);
  }

  final Set<int> mostFrequent = <int>{};
  int maxFreq = 0;
  for (final int f in freq.values) {
    if (f > maxFreq) {
      maxFreq = f;
      mostFrequent.clear();
    }
    if (f == maxFreq) {
      mostFrequent.add(f);
    }
  }

  final Set<int> candidates = <int>{};
  for (final int f in mostFrequent) {
    for (final int r in groups[f]!) {
      candidates.add(r);
    }
  }

  final Set<int> result = <int>{};
  for (final int r in candidates) {
    final int distance = (r - currentFloor).abs();
    if (distance > 0) {
      result.add(r);
    }
  }

  if (result.isEmpty) {
    final int farthest = candidates.reduce((int a, int b) {
      final int distA = (a - currentFloor).abs();
      final int distB = (b - currentFloor).abs();
      return distA > distB ? a : distB > distA ? b : a < b ? a : b;
    });
    result.add(farthest);
  }

  return result;
}

