List<int> fn0(List<int> packetSizes, int maxPacketSize, int maxGap) {
  if (packetSizes.isEmpty || maxPacketSize <= 0 || maxGap < 0) {
    return <int>[];
  }

  final int n = packetSizes.length;
  final List<int> dp = List<int>.filled(n, 0);
  final List<int> prev = List<int>.filled(n, -1);
  int bestLen = 0;
  int bestStart = -1;

  for (int i = 0; i < n; i++) {
    if (packetSizes[i] > maxPacketSize) {
      dp[i] = 0;
      prev[i] = -1;
      continue;
    }

    int maxRun = 0;
    int lastBad = -1;

    for (int j = i - 1; j >= 0; j--) {
      if (packetSizes[j] <= maxPacketSize) {
        final int gap = (i - j - 1).abs();
        if (gap <= maxGap) {
          final int cand = dp[j] + 1;
          if (cand > maxRun) {
            maxRun = cand;
            lastBad = j;
          }
        }
      } else {
        break;
      }
    }

    dp[i] = maxRun;
    prev[i] = lastBad;

    if (maxRun > bestLen) {
      bestLen = maxRun;
      bestStart = i - maxRun;
    } else if (maxRun == bestLen && (i - maxRun) < bestStart) {
      bestStart = i - maxRun;
    }
  }

  if (bestLen == 0) {
    return <int>[];
  }

  final List<int> result = <int>[];
  int idx = bestStart;

  while (idx != -1) {
    result.add(packetSizes[idx]);
    idx = prev[idx];
  }

  result.reverse();

  return result;
}

