bool fn0(List<int> sortedBpms, int targetBpm, int tolerance) {
  int left = 0;
  int right = sortedBpms.length - 1;

  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    int currentBpm = sortedBpms[mid];

    if (currentBpm == targetBpm) {
      return true;
    } else if (currentBpm < targetBpm) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  if (left >= sortedBpms.length) {
    return false;
  }

  int closestIndex = left - 1;
  int belowBpm = sortedBpms[closestIndex];

  if (belowBpm >= targetBpm - tolerance && belowBpm <= targetBpm + tolerance) {
    return true;
  }

  if (left < sortedBpms.length) {
    int aboveBpm = sortedBpms[left];

    if (aboveBpm >= targetBpm - tolerance && aboveBpm <= targetBpm + tolerance) {
      return true;
    }
  }

  return false;
}

