  List<int> left = List<int>.from(quantities);
  List<int> right = List<int>.from(quantities);
  int leftSum = 0, rightSum = 0;
  for (int i = 0; i < quantities.length; i++) {
    leftSum += left[i];
    rightSum += right[quantities.length - 1 - i];
  }
  int lo = 0, hi = quantities.length;
  while (lo <= hi) {
    int mid = (lo + hi) >> 1;
    if (mid > 0) leftSum -= left[mid - 1];
    if (mid + mid < quantities.length) rightSum -= right[quantities.length - mid];
    if (leftSum + rightSum == targetSum) {
      return {'index': mid, 'size': 2 * mid};
    } else if (leftSum + rightSum < targetSum) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return {'index': -1, 'size': 0};
}

