List<int> mergeSort(List<int> items) {
  if (items.length <= 1) return items;

  final mid = items.length ~/ 2;
  final left = mergeSort(items.sublist(0, mid));
  final right = mergeSort(items.sublist(mid));

  return merge(left, right);
}

List<int> merge(List<int> left, List<int> right) {
  final result = <int>[];
  var i = 0;
  var j = 0;

  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.add(left[i++]);
    } else {
      result.add(right[j++]);
    }
  }

  while (i < left.length) {
    result.add(left[i++]);
  }
  while (j < right.length) {
    result.add(right[j++]);
  }
  return result;
}

