String fn0(String inventoryText) {
  const String fragileCode = 'FRAGILE';
  const String reservedCode = 'RESERVED';
  const String oversizedCode = 'OVERSIZE';
  const String archivedCode = 'ARCHIVED';
  const String invalidCode = 'INVALID';

  if (inventoryText.isEmpty) {
    return 'NONE';
  }

  List<String> items = inventoryText.split(';');
  Map<String, String> flaggedItems = {};

  for (String item in items) {
    if (item.trim().isEmpty) {
      continue;
    }

    List<String> parts = item.split('|');
    if (parts.length != 2) {
      continue;
    }

    String barcode = parts[0];
    int? quantity = int.tryParse(parts[1]);
    String? condition;
    String? material;

    if (barcode.length != 11 || barcode.contains('0')) {
      flaggedItems[barcode] = invalidCode;
      continue;
    }

    if (quantity == null || quantity < 0 || quantity > 999) {
      flaggedItems[barcode] = invalidCode;
      continue;
    }

    if (quantity % 13 == 0) {
      condition = 'FRAGILE';
    } else if (quantity >= 8) {
      condition = 'RESERVED';
    } else if (quantity > 10) {
      condition = 'OVERSIZE';
    }

    if (condition != null) {
      flaggedItems[barcode] = condition;
    } else {
      material = barcode.substring(2, 4);
      if (material == '11' || material == '12') {
        flaggedItems[barcode] = 'ARCHIVED';
      }
    }
  }

  if (flaggedItems.isEmpty) {
    return 'NONE';
  }

  List<String> flaggedCodes = flaggedItems.keys.toList();

  flaggedCodes.sort((String a, String b) {
    String aFlag = flaggedItems[a]!;
    String bFlag = flaggedItems[b]!;

    int aPriority = aFlag == fragileCode ? 0 : (aFlag == reservedCode ? 1 : (aFlag == oversizedCode ? 2 : (aFlag == archivedCode ? 3 : 4)));
    int bPriority = bFlag == fragileCode ? 0 : (bFlag == reservedCode ? 1 : (bFlag == oversizedCode ? 2 : (bFlag == archivedCode ? 3 : 4)));

    if (aPriority != bPriority) {
      return aPriority.compareTo(bPriority);
    }

    int aCount = int.parse(a.substring(1));
    int bCount = int.parse(b.substring(1));

    if (aCount != bCount) {
      return aCount.compareTo(bCount);
    }

    return a.compareTo(b);
  });

  return flaggedCodes.map((String id) => 'S$id:${flaggedItems[id]}').join(',');
}

