  }

  List<int> prefix = List.filled(dailyBalances.length + 1, 0);
  for (int i = 1; i <= dailyBalances.length; i++) {
    prefix[i] = prefix[i - 1] + dailyBalances[i - 1];
  }

  int totalDeficit = 0;
  Set<int> seen = {};
  for (int v in prefix) {
    if (v < 0) {
      totalDeficit += -v;
    }
    seen.add(v);
  }

  int longestInterval = 0;
  Set<int> firstOccurrence = {};
  for (int i = 1; i < prefix.length; i++) {
    int val = prefix[i];
    if (firstOccurrence.containsKey(val)) {
      continue;
    }
    firstOccurrence.add(val);
    int left = 0;
    int right = i - 1;
    while (left <= right) {
      int mid = left + ((right - left) >> 1);
      if (prefix[mid] == val) {
        int intervalLength = i - mid;
        if (intervalLength > longestInterval) {
          longestInterval = intervalLength;
        }
        break;
      } else if (prefix[mid] < val) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  }

  return {
    'totalDeficitDays': totalDeficit,
    'distinctIntervals': seen.length,
    'longestInterval': longestInterval,
  };
}

