class QuadTreeNode {
  final Rectangle bounds;
  List<Point> points = [];
  QuadTreeNode? northeast;
  QuadTreeNode? northwest;
  QuadTreeNode? southwest;
  QuadTreeNode? southeast;

  QuadTreeNode(this.bounds);

  void insert(Point p) {
    if (!bounds.contains(p)) return;

    if (points.isEmpty) {
      points.add(p);
    } else if (northeast == null) {
      northeast = QuadTreeNode(Rectangle(bounds.centerX + bounds.halfWidth / 2, bounds.centerY + bounds.halfHeight / 2, bounds.halfWidth / 2, bounds.halfHeight / 2));
      northwest = QuadTreeNode(Rectangle(bounds.centerX - bounds.halfWidth / 2, bounds.centerY + bounds.halfHeight / 2, bounds.halfWidth / 2, bounds.halfHeight / 2));
      southwest = QuadTreeNode(Rectangle(bounds.centerX - bounds.halfWidth / 2, bounds.centerY - bounds.halfHeight / 2, bounds.halfWidth / 2, bounds.halfHeight / 2));
      southeast = QuadTreeNode(Rectangle(bounds.centerX + bounds.halfWidth / 2, bounds.centerY - bounds.halfHeight / 2, bounds.halfWidth / 2, bounds.halfHeight / 2));

      northeast?.insert(p);
      northwest?.insert(p);
      southwest?.insert(p);
      southeast?.insert(p);
    } else {
      northeast?.insert(p);
      northwest?.insert(p);
      southwest?.insert(p);
      southeast?.insert(p);
    }
  }

  List<Point> query(Rectangle range) {
    List<Point> result = [];

    for (var p in points) {
      if (range.contains(p)) {
        result.add(p);
      }
    }

    if (northeast != null) {
      result.addAll(northeast!.query(range));
      result.addAll(northwest!.query(range));
      result.addAll(southwest!.query(range));
      result.addAll(southeast!.query(range));
    }

    return result;
  }
}

