class QuadTreeNode {
  final List<Point> points;
  final Rectangle bounds;
  QuadTreeNode? northeast;
  QuadTreeNode? northwest;
  QuadTreeNode? southeast;
  QuadTreeNode? southwest;
  bool isLeaf;

  QuadTreeNode(this.points, this.bounds) {
    this.points = List<Point>.from(points);
    this.bounds = Rectangle(bounds.centerX, bounds.centerY, bounds.halfWidth, bounds.halfHeight);
    this.isLeaf = true;
    this.northeast = null;
    this.northwest = null;
    this.southeast = null;
    this.southwest = null;
  }

  void subdivide() {
    if (!isLeaf || points.length < 4) return;

    double halfW = bounds.halfWidth / 2;
    double halfH = bounds.halfHeight / 2;

    northeast = QuadTreeNode([], Rectangle(
        bounds.centerX + halfW, bounds.centerY + halfH, halfW, halfH));
    northwest = QuadTreeNode([], Rectangle(
        bounds.centerX - halfW, bounds.centerY + halfH, halfW, halfH));
    southeast = QuadTreeNode([], Rectangle(
        bounds.centerX - halfW, bounds.centerY - halfH, halfW, halfH));
    southwest = QuadTreeNode([], Rectangle(
        bounds.centerX + halfW, bounds.centerY - halfH, halfW, halfH));

    for (var p in points) {
      if (northeast!.containsPoint(p)) {
        northeast!.points.add(p);
      } else if (northwest!.containsPoint(p)) {
        northwest!.points.add(p);
      } else if (southeast!.containsPoint(p)) {
        southeast!.points.add(p);
      } else {
        southwest!.points.add(p);
      }
    }

    points.clear();
    isLeaf = false;
  }

  void insert(Point p) {
    if (!bounds.containsPoint(p)) return;

    if (isLeaf) {
      points.add(p);
      subdivide();
    } else {
      if (northeast!.containsPoint(p)) {
        northeast!.insert(p);
      } else if (northwest!.containsPoint(p)) {
        northwest!.insert(p);
      } else if (southeast!.containsPoint(p)) {
        southeast!.insert(p);
      } else {
        southwest!.insert(p);
      }
    }
  }

  List<Point> query(Rectangle range) {
    List<Point> pointsFound = [];

    if (!bounds.intersects(range)) return pointsFound;

    if (isLeaf) {
      for (var p in points) {
        if (range.containsPoint(p)) {
          pointsFound.add(p);
        }
      }
    } else {
      pointsFound.addAll(northeast!.query(range));
      pointsFound.addAll(northwest!.query(range));
      pointsFound.addAll(southeast!.query(range));
      pointsFound.addAll(southwest!.query(range));
    }

    return pointsFound;
  }
}

