class Grid {
  final int bucketsPerSide;
  final double maxRange;
  final List<Set<Point>> buckets;
  final Point _origin;
  final double _bucketSize;
  final Set<Point> _pointsWithinRange = HashSet<Point>();

  Grid(this.bucketsPerSide, this.maxRange, this._origin)
      : _bucketSize = maxRange / bucketsPerSide,
        buckets = List.generate(
            bucketsPerSide * bucketsPerSide, (_) => HashSet<Point>());

  int _bucketIndex(Point p) =>
      bucketsPerSide *
          (p.y - _origin.y).roundToDouble() ~/ _bucketSize +
      (p.x - _origin.x).roundToDouble() ~/ _bucketSize;

  void add(Point p) {
    buckets[_bucketIndex(p)].add(p);
  }

  void query(Rectangle range) {
    _pointsWithinRange.clear();
    final rangeCenter = range.center;
    final rangeHalfWidth = range.halfWidth;
    final rangeHalfHeight = range.halfHeight;
    final rangeMinX = rangeCenter.x - rangeHalfWidth;
    final rangeMaxX = rangeCenter.x + rangeHalfWidth;
    final rangeMinY = rangeCenter.y - rangeHalfHeight;
    final rangeMaxY = rangeCenter.y + rangeHalfHeight;

    for (var bucketIdx = 0; bucketIdx < buckets.length; bucketIdx++) {
      final bucket = buckets[bucketIdx];
      if (bucket.isEmpty) continue;

      final bucketX = bucketIdx ~/ bucketsPerSide;
      final bucketY = bucketIdx % bucketsPerSide;
      final bucketCenterX = _origin.x + bucketX * _bucketSize;
      final bucketCenterY = _origin.y + bucketY * _bucketSize;
      final bucketMinX = bucketCenterX - _bucketSize / 2;
      final bucketMaxX = bucketCenterX + _bucketSize / 2;
      final bucketMinY = bucketCenterY - _bucketSize / 2;
      final bucketMaxY = bucketCenterY + _bucketSize / 2;

      if (bucketMinX < rangeMaxX &&
          bucketMaxX > rangeMinX &&
          bucketMinY < rangeMaxY &&
          bucketMaxY > rangeMinY) {
        for (final p in bucket) {
          if (range.contains(p)) {
            _pointsWithinRange.add(p);
          }
        }
      }
    }
  }

  void printPointsWithinRange(double range) {
    final rangeSquare = range * range;
    print('Points within range $range:');
    for (final p in _pointsWithinRange) {
      if ((p.x - _origin.x).abs() + (p.y - _origin.y).abs() <= rangeSquare) {
        print(p);
      }
    }
  }
}

