    dp[i][maxCancels] = includeProb + excludeProb;

    for (int c = 0; c < maxCancels; c++) {
      double include = 0.0;
      for (int prevC = 0; prevC <= c; prevC++) {
        include += dp[i - 1][prevC] * baseProb;
      }
      double exclude = dp[i - 1][c] * baseProb;
      dp[i][c] = include + exclude;
    }

    if (phase == "CANCEL") {
      for (int c = 0; c <= maxCancels; c++) {
        if (c > 0) dp[i][c] += dp[i - 1][c - 1] * baseProb;
      }
