  neptune(102.43, 49528, 30.069);

  final double mass;      // in Earth masses
  final double radius;    // in Earth radii
  final double distance;  // in AU

  const Planet(this.mass, this.radius, this.distance);

  double get surfaceGravity {
    const g = 6.67300e-11; 
    const me = 5.972e24;   
    const re = 6.371e6;    
    return (g * mass * me) / (re * radius * radius);
  }

  double get orbitalPeriod => sqrt((distance * distance) / (mass * 27)); 

  double get orbitalVelocity => sqrt((2 * 27 * (1 - distance) / distance) * 24); 

  double get escapeVelocity {
    const g = 6.67300e-11;
    const me = 5.972e24;
    const re = 6.371e6;
    return sqrt(2 * g * mass * me / (re * radius));
  }

  double get solarLuminosity {
    const luminositySun = 3.828e26;
    return luminositySun * (mass / 1.0) * (radius / 1.0) * (radius / 1.0);
  }

  double get transitDuration {
    double r1 = radius;           
    double r2 = 1.0;              
    double a = distance;           
    double b = sqrt(a * a - r2 * r2); 
    return (pi * (r1 + r2)) / (sqrt(27) * sqrt(b)); 
  }
}

