  final data = [
    [1.0, 2.0],
    [1.5, 1.8],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.6],
    [9.0, 11.0],
    [8.0, 2.0],
    [10.0, 2.0],
    [9.0, 3.0],
  ];

  final int k = 3;

  final Random rand = Random(42);

  List<List<double>> centroids = [];
  Set<int> usedIndices = {};

  while (centroids.length < k) {
    int idx = rand.nextInt(data.length);
    if (!usedIndices.contains(idx)) {
      usedIndices.add(idx);
      centroids.add(data[idx].toList());
    }
  }

  const double eps = 1e-4;
  const int maxIterations = 100;
  int iteration = 0;

  bool converged = false;

  while (!converged && iteration < maxIterations) {
    Map<int, List<List<double>>> clusters = {};
    List<List<double>> oldCentroids = centroids.toList();

    for (int c = 0; c < k; c++) {
      clusters[c] = [];
    }

    for (List<double> point in data) {
      double minDist = double.infinity;
      int bestCluster = 0;

      for (int c = 0; c < k; c++) {
        double dist = 0.0;
        for (int d = 0; d < point.length; d++) {
          dist += pow(point[d] - centroids[c][d], 2);
        }
        dist = sqrt(dist);

        if (dist < minDist) {
          minDist = dist;
          bestCluster = c;
        }
      }

      clusters[bestCluster]!.add(point);
    }

    converged = true;

    for (int c = 0; c < k; c++) {
      if (clusters[c]!.isEmpty) {
        clusters[c] = [oldCentroids[c]];
      } else {
        List<double> sum = List<double>.filled(clusters[c]!.first.length, 0.0);
        for (var point in clusters[c]!) {
          for (int d = 0; d < point.length; d++) {
            sum[d] += point[d];
          }
        }
        for (int d = 0; d < sum.length; d++) {
          sum[d] /= clusters[c]!.length;
        }

        List<double> old = oldCentroids[c];
        double diff = 0.0;
        for (int i = 0; i < sum.length; i++) {
          double delta = sum[i] - old[i];
          diff += delta * delta;
        }

        if (diff > eps * eps) {
          converged = false;
        }

        oldCentroids[c] = sum;
      }
    }

    centroids = oldCentroids;
    iteration++;
  }

  print('Converged in $iteration iteration(s).');

  for (int c = 0; c < k; c++) {
    print('Cluster $c centroid: ${centroids[c]}');
  }

  double pts = 0.0;
  for (int c = 0; c < k; c++) {
    for (var point in data) {
      double dist = 0.0;
      for (int d = 0; d < point.length; d++) {
        dist += pow(point[d] - centroids[c][d], 2);
      }
      dist = sqrt(dist);
      pts += dist;
    }
  }
  print('Points: $pts\n');
}

