    return {'totalPassableCells': 0, 'segmentCount': 0, 'maxSegmentLength': 0, 'minSegmentLength': 0, 'maxSegmentScore': 0};
  }

  final rows = grid.length;
  final cols = grid[0].length;
  final passable = List.generate(rows, (_) => List.filled(cols, 0));

  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      final moisture = grid[r][c];
      final temp = (r * cols + c) / 2;
      if (moisture > 0 && moisture > temp) {
        passable[r][c] = 1;
      }
    }
  }

  final visited = List.generate(rows, (_) => List.filled(cols, 0));
  final counts = [0, 0];
  var maxLen = 0;
  var minLen = cols * rows + 1;
  var maxScore = 0;

  void dfs(int r, int c, int startIdx, int score) {
    if (!passable[r][c] || visited[r][c] == 1) return;
    visited[r][c] = 1;
    counts[0]++;
    counts[1] += grid[r][c];
    if (dfs(r - 1, c, startIdx, score + grid[r][c])) return;
    if (dfs(r + 1, c, startIdx, score + grid[r][c])) return;
    if (dfs(r, c - 1, startIdx, score + grid[r][c])) return;
    if (dfs(r, c + 1, startIdx, score + grid[r][c])) return;
    visited[r][c] = 0;
  }

  for (var r = 0; r < rows; r++) {
    for (var c = 0; c < cols; c++) {
      if (passable[r][c]) {
        dfs(r, c, counts[0], counts[1]);
      }
    }
  }

