  }

  return {
    'totalPassableCells': counts[0],
    'segmentCount': counts[0] == cols * rows ? 1 : counts[0],
    'maxSegmentLength': maxLen > 0 ? maxLen : cols * rows,
    'minSegmentLength': minLen,
    'maxSegmentScore': maxScore,
  };
}

