  Set<int> usedSlots = {};
  List<int> timeline = [];
  Set<int> warnings = {};

  int currentLoad = 0;
  int lastUsedIndex = -1;

  int findFirstUnused(int start) {
    for (int i = start; i < capacity; i++) {
      if (!usedSlots.contains(i)) {
        return i;
      }
    }
    return -1;
  }

  int findBestSlot(int start) {
    int bestIndex = -1;
    int bestDistance = 0;
    int firstUnused = findFirstUnused(start);

    if (firstUnused != -1) {
      return firstUnused;
    }

    int wrapStart = (start + capacity) % capacity;
    for (int i = wrapStart; i < start; i++) {
      if (!usedSlots.contains(i)) {
        return i;
      }
    }

    for (int i = 0; i < capacity; i++) {
      if (!usedSlots.contains(i)) {
        return i;
      }
    }

    for (int i = 0; i < timeline.length; i++) {
      int slot = timeline[i];
      int distance = (slot - start + capacity) % capacity;
      if (distance > bestDistance) {
        bestDistance = distance;
        bestIndex = slot;
      }
    }

    int wrappedStart = (start + capacity) % capacity;
    for (int i = wrappedStart; i < start; i++) {
      int distance = (i - start + capacity) % capacity;
      if (distance > bestDistance) {
        bestDistance = distance;
        bestIndex = i;
      }
    }

    return bestIndex;
  }

  for (int request in requests) {
    int slot = request % capacity;

    if (slots.containsKey(slot)) {
      slots[slot] = slots[slot]! + 1;
      timeline.add(slot);
      if (slots[slot]! > 1) {
        warnings.add(slot);
      }
    } else {
      slots[slot] = 1;
      int best = findBestSlot(slot);

      if (usedSlots.contains(best)) {
