  }

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  int g = deck[0];
  int minVal = deck[0];
  int maxVal = deck[0];
  for (int i = 1; i < deck.length; i++) {
