      int subGcd = gcdOfRange;
      for (int j = i; j < i + mid; j++) {
        subGcd = gcd(subGcd, deck[j]);
      }
      if (subGcd >= threshold) {
        lo = mid;
        break;
      }
    }
    if (lo < hi && lo + deck.length - lo >= 0) {
      int allGcd = gcdOfRange;
      for (int j = lo; j < lo + deck.length - lo; j++) {
        allGcd = gcd(allGcd, deck[j]);
      }
      if (allGcd < threshold) {
        lo = mid;
      }
    }
  }

  int bestGcd = gcdOfRange;
  for (int j = lo; j < lo + deck.length - lo; j++) {
