@pragma('vm:entry-point')
Set<int> fn0(List<List<int>> rolls) {
  if (rolls.isEmpty) return <int>{};
  int rows = rolls.length;
  int cols = rolls[0].length;
  for (int r = 1; r < rows; r++) {
    if (rolls[r].length != cols) return <int>{};
  }
  if (cols < 2) return <int>{};

  List<List<int>> dp = List.generate(
    rows,
    (_) => List<int>.filled(cols, 0),
  );
  int maxVal = -1;

  for (int c = 0; c < cols; c++) {
    int val = rolls[0][c];
    if (val >= 2 && val <= 6) {
      dp[0][c] = val;
      if (val > maxVal) maxVal = val;
    }
  }

  for (int r = 1; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int val = rolls[r][c];
      if (val >= 2 && val <= 6) {
        bool hasPrev = false;
        if (c > 0) hasPrev = dp[r][c - 1] > 0;
        if (hasPrev) {
          dp[r][c] = dp[r][c - 1] + val;
          if (dp[r][c] > maxVal) maxVal = dp[r][c];
        }
      }
    }
  }

  Set<int> result = <int>{};
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (dp[r][c] == maxVal) {
        result.add(c);
      }
    }
  }
  return result;
}

