int fn0(List<int> signalStrengths) {
  if (signalStrengths.length <= 1) return 0;
  List<int> sorted = List<int>.from(signalStrengths);
  sorted.sort((a, b) {
    int crossingsA = (a ~/ 2) + (a % 2);
    int crossingsB = (b ~/ 2) + (b % 2);
    int aWeight = a * crossingsA;
    int bWeight = b * crossingsB;
    if (aWeight != bWeight) {
      return bWeight.compareTo(aWeight);
    }
    if (a != b) {
      return a.compareTo(b);
    }
    return crossingsA.compareTo(crossingsB);
  });
  int total = 0;
  for (int i = 1; i < sorted.length; i++) {
    if (sorted[i] > sorted[i - 1]) {
      total += sorted[i] - sorted[i - 1];
    }
  }
  return total;
}

