@pragma('vm:never-inline')
@pragma('vm:entry-point')
List<int> fn0(List<List<int>> readings, int maxDifference) {
  if (readings.isEmpty || readings[0].isEmpty) return [];
  int rows = readings.length;
  int cols = readings[0].length;
  List<int> order = [];
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));
  List<List<int>> deltas = [[-1, 0], [0, 1], [1, 0], [0, -1]];

  void dfs(int r, int c) {
    visited[r][c] = true;
    order.add(readings[r][c]);
    for (List<int> d in deltas) {
      int nr = r + d[0];
      int nc = c + d[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc] &&
          (readings[nr][nc] - readings[r][c]).abs() <= maxDifference) {
        dfs(nr, nc);
      }
    }
  }

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (!visited[r][c]) {
        dfs(r, c);
      }
    }
  }
  return order;
}

