List<int> fn0(List<int> samples, int windowSize, int minSamples, int maxSpread) {
  List<int> result = [];
  for (int i = 0; i <= samples.length - windowSize; i++) {
    int start = i;
    int end = i + windowSize;
    int minS = samples[start];
    int maxS = samples[start];
    int sum = 0;
    int count = 0;
    for (int j = start; j < end; j++) {
      int val = samples[j];
      sum += val;
      if (val < minS) minS = val;
      if (val > maxS) maxS = val;
      count++;
    }
    if (count >= minSamples && (maxS - minS) <= maxSpread) {
      result.add(sum ~/ count);
    }
  }
  return result;
}

