List<int> fn0(List<int> packets, int windowSize) {
  if (windowSize <= 0 || packets.length < windowSize) {
    return List.filled(packets.length, -1);
  }

  int maxLen = packets.length - windowSize + 1;
  List<int> result = List.filled(maxLen, 0);

  int maxVal = packets[0];
  int minVal = packets[0];
  for (int i = 0; i < windowSize; i++) {
    if (packets[i] > maxVal) {
      maxVal = packets[i];
    }
    if (packets[i] < minVal) {
      minVal = packets[i];
    }
  }
  result[0] = maxVal - minVal;

  for (int i = 1; i < maxLen; i++) {
    if (packets[i - 1] == maxVal) {
      maxVal = packets[i];
      for (int j = i; j < i + windowSize - 1; j++) {
        if (packets[j] > maxVal) {
          maxVal = packets[j];
        }
      }
    }
    if (packets[i - 1] == minVal) {
      minVal = packets[i];
      for (int j = i; j < i + windowSize - 1; j++) {
        if (packets[j] < minVal) {
          minVal = packets[j];
        }
      }
    }
    result[i] = maxVal - minVal;
  }

  return result;
}

